int unpack_cdf_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                            size_t *count) {
    uint64_t offset;
    size_t i;
    int ret = -1;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (h->si_offset >= sst->length || h->si_offset + h->si_size > sst->length) {
        return -1;
    }

    offset = h->si_offset;
    ssi->magic = cdf_get_le32(sst->data + offset);
    offset += 4;

    if (ssi->magic != CDF_MAGIC_SI) {
        return -1;
    }

    ssi->byte_order = cdf_get_le16(sst->data + offset);
    offset += 2;
    ssi->os_version = cdf_get_le16(sst->data + offset);
    offset += 2;
    ssi->os_type = cdf_get_le16(sst->data + offset);
    offset += 2;
    ssi->class = cdf_get_le32(sst->data + offset);
    offset += 4;
    ssi->property_count = cdf_get_le16(sst->data + offset);
    offset += 2;

    *count = ssi->property_count;
    *info = (cdf_property_info_t *)malloc(sizeof(cdf_property_info_t) * *count);
    if (!*info) {
        return -1;
    }

    for (i = 0; i < *count; i++) {
        if (offset + sizeof(cdf_property_info_t) > h->si_offset + h->si_size) {
            goto error;
        }

        (*info)[i].id = cdf_get_le16(sst->data + offset);
        offset += 2;
        (*info)[i].type = cdf_get_le16(sst->data + offset);
        offset += 2;
        (*info)[i].offset = cdf_get_le32(sst->data + offset);
        offset += 4;
        (*info)[i].length = cdf_get_le32(sst->data + offset);
        offset += 4;
    }

    ret = 0;

error:
    if (ret != 0 && *info) {
        free(*info);
        *info = NULL;
    }

    return ret;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h, cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count) {
    uint32_t offset;
    size_t i;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    offset = h->section_decl;
    if (offset >= sst->size) {
        return -1;
    }

    ssi->byte_order = CDF_BYTEORDER_LITTLE;
    ssi->os_version = h->os_version;
    ssi->os_type = h->os_type;
    ssi->class = h->class;
    ssi->prop_count = h->prop_count;

    *count = ssi->prop_count;
    *info = (cdf_property_info_t *)malloc(*count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (i = 0; i < *count; i++) {
        if (offset + sizeof(cdf_property_info_t) > sst->size) {
            free(*info);
            *info = NULL;
            *count = 0;
            return -1;
        }
        memcpy(&(*info)[i], &sst->data[offset], sizeof(cdf_property_info_t));
        offset += sizeof(cdf_property_info_t);
    }

    return 0;
}

int unpack_cdf_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi,
                            cdf_property_info_t **info, size_t *count) {
    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    // Read the byte order, OS version, OS type, class, and property count from the stream
    if (sst->read(sst, &ssi->byte_order, sizeof(ssi->byte_order), h->offset_summary_info) != sizeof(ssi->byte_order)) {
        return -1;
    }

    if (sst->read(sst, &ssi->os_version, sizeof(ssi->os_version), h->offset_summary_info + 2) != sizeof(ssi->os_version)) {
        return -1;
    }

    if (sst->read(sst, &ssi->os_type, sizeof(ssi->os_type), h->offset_summary_info + 4) != sizeof(ssi->os_type)) {
        return -1;
    }

    if (sst->read(sst, &ssi->class, sizeof(ssi->class), h->offset_summary_info + 6) != sizeof(ssi->class)) {
        return -1;
    }

    if (sst->read(sst, &ssi->property_count, sizeof(ssi->property_count), h->offset_summary_info + 8) != sizeof(ssi->property_count)) {
        return -1;
    }

    // Allocate memory for the property info array
    *info = (cdf_property_info_t *)malloc(ssi->property_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    // Read each property info from the stream
    for (size_t i = 0; i < ssi->property_count; ++i) {
        size_t offset = h->offset_summary_info + 12 + i * sizeof(cdf_property_info_t);
        if (sst->read(sst, &(*info)[i], sizeof(cdf_property_info_t), offset) != sizeof(cdf_property_info_t)) {
            free(*info);
            *info = NULL;
            return -1;
        }
    }

    *count = ssi->property_count;
    return 0;
}

int unpack_cdf_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi,
                            cdf_property_info_t **info, size_t *count) {
    const uint8_t *data;
    size_t data_size;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (h->section_declaration_offset > sst->size) {
        return -1;
    }

    data = sst->data + h->section_declaration_offset;
    data_size = sst->size - h->section_declaration_offset;

    if (data_size < sizeof(cdf_summary_info_header_t)) {
        return -1;
    }

    memcpy(ssi, data, sizeof(cdf_summary_info_header_t));

    if (data_size < ssi->property_count * sizeof(cdf_property_info_t) +
                     sizeof(cdf_summary_info_header_t)) {
        return -1;
    }

    *info = malloc(ssi->property_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (size_t i = 0; i < ssi->property_count; i++) {
        memcpy(&(*info)[i], data + sizeof(cdf_summary_info_header_t) + i * sizeof(cdf_property_info_t),
               sizeof(cdf_property_info_t));
    }

    *count = ssi->property_count;
    return 0;
}

int cdf_unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi,
                            cdf_property_info_t **info, size_t *count) {
    uint32_t offset;
    uint32_t size;
    uint32_t i;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (h->section_offset > sst->size) {
        return -1;
    }

    if (sst->read(sst, ssi, h->section_size, h->section_offset) != h->section_size) {
        return -1;
    }

    offset = ssi->property_offset;
    size = ssi->property_count * sizeof(cdf_property_info_t);

    if (offset > sst->size || size > sst->size - offset) {
        return -1;
    }

    *info = (cdf_property_info_t *)malloc(size);
    if (!*info) {
        return -1;
    }

    for (i = 0; i < ssi->property_count; i++) {
        if (sst->read(sst, &(*info)[i], sizeof(cdf_property_info_t), offset) !=
            sizeof(cdf_property_info_t)) {
            free(*info);
            *info = NULL;
            return -1;
        }
        offset += sizeof(cdf_property_info_t);
    }

    *count = ssi->property_count;
    return 0;
}
